-- Business question: How do completed-order revenue and customer counts vary by region and month?
-- INNER JOIN is appropriate because this report covers orders and their customers; COUNT(DISTINCT customer_id) is necessary so repeat orders from one customer are counted once per region-month.
SELECT c.region, o.order_month, COUNT(*) AS number_of_orders, COUNT(DISTINCT c.customer_id) AS number_of_customers, SUM(o.amount) AS total_revenue, AVG(o.amount) AS average_revenue FROM orders AS o JOIN customers AS c ON o.customer_id = c.customer_id WHERE o.status = 'completed' GROUP BY c.region, o.order_month ORDER BY c.region, o.order_month;
